// Listing Components
.quarto-post .listing-categories .listing-category {
  border: solid 1px $foreground;

  &:hover {
    color: $foreground;
  }
}

.quarto-grid-item .listing-categories .listing-category:hover,
.quarto-listing-category .category:hover,
.quarto-title .quarto-categories .quarto-category a:hover {
  color: $foreground;
}

.quarto-listing-category .category {
  text-transform: uppercase;
}

.listing-description {
  color: $foreground;
}

// Footer Link
.footer a:hover {
  color: $link-color;
}

// Custom Styles

.picture {
  border-style: solid;
  border-width: 3pt;
  border-color: $background;
  border-radius: 50%;
  padding: 5pt;
  height: 50%;
  width: auto;
  max-width: 200px !important;
  min-width: 100px;
}

@media (max-width: 768px) {
  .quarto-layout-row {
    flex-direction: column;
  }

  .quarto-layout-cell {
    flex-basis: 100% !important;
    margin-bottom: 1rem;
  }

  .quarto-figure-spacer {
    display: none;
  }
}

.quarto-alternate-formats,
.quarto-code-links,
.quarto-other-links {
  h2 {
    display: none;
  }

  ul {
    margin-bottom: 0;
  }
}

@function body-mix($weight) {
  @return mix($background, $foreground, $weight);
}

// Quarto Components
#quarto-back-to-top {
  box-shadow: 0 .2rem .5rem body-mix(95%), 0 0 .05rem body-mix(95%);
  color: body-mix(5%);
}

.quarto-title-banner {
  margin-bottom: 0em;
  color: $foreground;
  background-color: body-mix(99%);

  a {
    color: body-mix(50%);

    &:hover {
      color: $foreground;
    }
  }

  .quarto-title .title {
    color: $foreground;
  }
}

.quarto-title-breadcrumbs .breadcrumb li:last-of-type a,
.quarto-secondary-nav nav.quarto-page-breadcrumbs .breadcrumb li:last-of-type a {
  color: body-mix(50%);
  font-weight: 600;
}

// Pagination & Forms
.page-item {
  &.active .page-link,
  .page-link:hover {
    color: $background;
    background-color: $foreground;
    border-color: $background;
  }

  &.disabled .page-link {
    color: $foreground;
    background-color: $background;
  }
}

.page-link:hover {
  color: $background;
  background-color: $foreground;
  border-color: $background;
}

.input-group-text {
  color: $background;
  background-color: $foreground;
}

// Code Styling
code,
a > code {
  color: $background;
  background-color: $foreground;
}

a > code {
  text-decoration: underline;
}

p code:not(.sourceCode),
li code:not(.sourceCode) {
  background-color: $foreground;
}

nav p code:not(.sourceCode),
nav li code:not(.sourceCode),
nav td code:not(.sourceCode) {
  background-color: $foreground !important;
}

div.sourceCode {
  background-color: body-mix(95%);
}

.code-annotation-gutter {
  background-color: body-mix(95%);
}

.code-annotated .code-copy-button {
  margin-right: 1.5em;
}

// List Groups
.list-group-item-action {
  &:hover,
  &:focus {
    color: unset;
    background-color: unset;
  }
}

// About Section
img.about-image {
  border-radius: 50%;
  border-style: solid;
  border-width: 2pt;
  border-color: $foreground;
  padding: 5pt;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background: $foreground;
    transition: .5s;
    transform: scale(.9);
    z-index: -1;
  }

  &:hover {
    color: $foreground;
    box-shadow: 0 0 10px $foreground;
    text-shadow: 0 0 10px $foreground;

    &::before {
      transform: scale(1.1);
      box-shadow: 0 0 30px $foreground;
    }
  }
}

// About Entity Components
.about-entity {
  #title-block-header.quarto-title-block.default .quarto-title .title:hover {
    color: $foreground;
    text-shadow: 0 0 10px $foreground;
  }
}

.quarto-about-solana .about-entity {
  .about-links {
    column-gap: 0;
    .about-link {
      font-size: 1.5em;
      border-style: none;
      transition: all .35s ease;

      &:hover {
        transform: scale(1.25);
      }
    }

    @media(max-width: 992px) {
      flex-direction: row;
      justify-content: center;
      flex-wrap: wrap;
    }
  }
}

.quarto-about-trestles .about-entity {
  .about-link {
    color: mix($link-color, $background, 50%);
    border: solid 1px $foreground;

    &:hover {
      color: $link-color;
      font-weight: bold;
    }
  }
}

// Navbar
